/* Exact Bette screenshots generated by scripts/bette-capture-exact.js after
 * checking the real manufacturer's 3D canvas, SKU, dimensions and colour. */
(function(root,factory){const api=factory(root);if(typeof module==='object'&&module.exports)module.exports=api;if(root)root.HydroBetteExactRenders=api;})(typeof window==='object'?window:null,function(root){
 'use strict';
 let manifestPromise=null;
 const name=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'');
 const sourceLink=s=>{
  try{const u=new URL(s);return u.protocol==='https:'&&u.hostname==='www.my-bette.com'&&
   u.pathname==='/fr/configurator'&&/^\d+$/.test(u.searchParams.get('product')||'')&&
   /^\d+$/.test(u.searchParams.get('variant')||'');}catch{return false}
 };
 function eligible(record,row){
  if(!record||record.scope!=='verified-3d-screenshot'||row?.reference!==record.reference)return false;
  if(!/^[A-Z0-9-]+$/.test(record.reference))return false;
  if(record.image!=='/bette-renders/'+record.reference+'.png')return false;
  if(Number(row.lengthMm)!==Number(record.lengthMm)||Number(row.widthMm)!==Number(record.widthMm))return false;
  if(!sourceLink(record.sourceUrl))return false;
  const shade=name(row.color||'');
  if(shade&&!['standard','blanc','blancbrillant','white','weiss','000'].includes(shade)&&!shade.includes(name(record.color)))return false;
  const code=String(record.reference).split('-').pop();
  if(code!==record.colorCode)return false;
  return true;
 }
 async function load(fetcher=root?.fetch){
  if(manifestPromise)return manifestPromise;
  if(!fetcher)return {};
  manifestPromise=fetcher('/bette-renders/manifest.json',{credentials:'same-origin'})
    .then(r=>r.ok?r.json():{}).catch(()=>({}));
  return manifestPromise;
 }
 async function find(row,fetcher){
  const data=await load(fetcher);
  const item=data?.[String(row?.reference||'')];
  return eligible(item,row)?item:null;
 }
 return {eligible,find,load};
});